class Solution:
    def setZeroes(self, matrix: List[List[int]]) -> None:
        """
        Do not return anything, modify matrix in-place instead.
        """
        rows = [0] * len(matrix)
        cols = [0] * len(matrix[0])

        for i in range(len(rows)):
            for j in range(len(cols)):
                if matrix[i][j] == 0:
                    rows[i], cols[j] = 1, 1

        for i in range(len(rows)):
            if rows[i] != 0:
                for j in range(len(cols)):
                    matrix[i][j] = 0

        for j in range(len(cols)):
            if cols[j] != 0:
                for i in range(len(rows)):
                    matrix[i][j] = 0
